	oldPort, newPort := freePort(t), freePort(t)
	a, _ := routerServingOn(t, oldPort)
	opened := runCmd(t, mustCmd(a.Update(forward.OpenMsg{Name: "api.localhost", Target: httpBackend(t, "x")}))).(forward.OpenedMsg)
